from specflow.refmodel.temporal import after, throughout, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    applies = _holds({"ena": 1, "nReset": 1, "rst": 0})
    closes = _any([{"cmd_ack": 1}, {"al": 1}])
    follows = True  # normalized activation.effect_follows

    windows = after(trace, applies, until=closes)

    def const_low(r):
        return r["outputs"].get("scl_o") == 0 and r["outputs"].get("sda_o") == 0

    return worst([throughout(w, const_low, after_activation=follows) for w in windows])

def decide(trace):
    from specflow.refmodel.temporal import after, worst

    # Activation predicate: cmd==4, ena==1, nReset==1, rst==0
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    activation = {"cmd": 4, "ena": 1, "nReset": 1, "rst": 0}
    closes = [{"cmd_ack": 1}, {"al": 1}]

    follows = True  # activation.effect_follows

    windows = after(trace, _holds(activation), until=_any(closes))
    if not windows:
        return (None, None, 'the WRITE command activation never occurred')

    verdicts = []
    for w in windows:
        # rows is the list of distinct states the window spans
        rows = list(w.rows)
        # when effect_follows is True, evaluate from the row AFTER the activation
        if follows:
            if len(rows) <= 1:
                # no post-activation state to observe
                if not w.closed:
                    verdicts.append((None, None, 'window ran off the end before post-activation states'))
                else:
                    verdicts.append((False, w.edge, 'no post-activation states to observe WRITE bit cycles'))
                continue
            rows = rows[1:]

        found_cycle = False
        window_bad = False
        bad_edge = None
        bad_detail = ''

        i = 0
        while i < len(rows):
            r = rows[i]
            # look for the high phase release: scl_oen == 1
            if r['outputs'].get('scl_oen') == 1:
                # find a later low phase scl_oen == 0
                j = i + 1
                while j < len(rows) and rows[j]['outputs'].get('scl_oen') != 0:
                    j += 1
                if j < len(rows) and rows[j]['outputs'].get('scl_oen') == 0:
                    # found a candidate WRITE bit cycle spanning rows[i..j]
                    found_cycle = True
                    # require sda_oen == din throughout the bit cycle
                    for k in range(i, j + 1):
                        sda = rows[k]['outputs'].get('sda_oen')
                        dinv = rows[k]['inputs'].get('din')
                        if sda != dinv:
                            window_bad = True
                            bad_edge = rows[k]['edge']
                            bad_detail = (f'sda_oen ({sda}) != din ({dinv}) during WRITE bit cycle ' 
                                          f'at window row index {k}')
                            break
                    if window_bad:
                        break
                    # continue search after this low-phase row
                    i = j + 1
                    continue
                # else no matching low-phase found after this high-phase in the available rows
            i += 1

        if window_bad:
            verdicts.append((False, bad_edge, bad_detail))
        else:
            if not found_cycle:
                # no observed high->low scl_oen transition in this window
                if not w.closed:
                    verdicts.append((None, None, 'no WRITE bit cycle observed before trace end'))
                else:
                    verdicts.append((False, w.edge, 'no WRITE bit cycle observed in this command window'))
            else:
                verdicts.append((True, None, 'observed WRITE bit cycles drive/release SDA according to din and toggle SCL open-drain enable'))

    return worst(verdicts)

from specflow.refmodel.temporal import after, edges, eventually, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row['outputs'].get(k, row['inputs'].get(k)) == v
                for k, v in cond.items())
        return p

    # "an active (non-NOP) command" was normalized as cmd=1, which is
    # I2C_CMD_START -- the one command during which the controller drives
    # SDA low itself, so "the controller expects SDA to be high" is
    # definitionally false there. The requirement's first disjunct is about
    # a transmitted high bit (din=1) read back low, which only a WRITE
    # (I2C_CMD_WRITE = 4) does.
    active = _holds({'cmd': 4, 'ena': 1, 'nReset': 1, 'rst': 0})

    alt1 = _holds({'din': 1, 'scl_i': 1, 'sda_i': 0})

    rose_sda = set(edges(trace, 'sda_i', 'rise'))

    def alt2(row):
        return row['edge'] in rose_sda and row['inputs'].get('scl_i') == 1

    def opens(row):
        return active(row) and (alt1(row) or alt2(row))

    def closes(row):
        return row['outputs'].get('cmd_ack') == 1 or row['outputs'].get('al') == 1

    windows = after(trace, opens, until=closes)

    return worst([
        eventually(w, lambda r: r['outputs'].get('al') == 1,
                   after_activation=True, strong=True)
        for w in windows
    ])

def decide(trace):
    # Inspect only declared ports. Activation: normal operation (nReset=1, rst=0).
    from specflow.refmodel.temporal import after, edges

    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    # Build activation windows: while nReset==1 and rst==0 (co-extensive)
    windows = after(trace, _holds({"nReset": 1, "rst": 0}))
    if not windows:
        return (None, None, 'normal-operation activation (nReset=1, rst=0) never occurred')

    # Treat dout changes as the sampling moments we must decide at.
    dout_edges = edges(trace, 'dout', 'change')

    saw_event = False
    saw_insufficient_history = False

    for w in windows:
        for rowref in w.rows:
            # rowref may be an int index or the row dict itself. Handle both.
            if isinstance(rowref, dict):
                row = rowref
                pos = row.get('index')
            else:
                pos = int(rowref)
                # guard: ensure pos is in bounds
                if pos < 0 or pos >= len(trace):
                    continue
                row = trace[pos]

            # The edges() helper returns the 'edge' numbers for transitions.
            if row.get('edge') not in dout_edges:
                continue

            # This is a dout-update sampling event during normal operation.
            saw_event = True

            # We require two prior distinct states to inspect the two sequential captures.
            # pos is the position in trace (distinct-state compressed). Need pos>=2.
            if pos < 2:
                saw_insufficient_history = True
                continue

            new_dout = row['outputs'].get('dout')
            prev1 = trace[pos - 1]['inputs'].get('sda_i')
            prev2 = trace[pos - 2]['inputs'].get('sda_i')

            # Two-stage synchroniser: the input must have been stable across the
            # two sequential captures before the sampled output appears.
            if prev1 == new_dout and prev2 == new_dout:
                # OK for this sampling event
                continue
            else:
                return (False, row.get('edge'),
                        f'dout changed to {new_dout} at edge {row.get("edge")} but sda_i was not stable across two prior samples (idx-2.sda_i={prev2}, idx-1.sda_i={prev1})')

    if not saw_event:
        return (None, None, 'no dout sampling events observed during normal operation')
    if saw_insufficient_history:
        return (None, None, 'observed sampling event(s) but insufficient prior history to decide (need two prior distinct states)')
    return (True, None, 'all observed dout sampling events were backed by sda_i stable across two prior captures')

def decide(trace):
    # Activation: operate only when normal operation is enabled
    def active(r):
        return (r['inputs'].get('nReset', 1) == 1
                and r['inputs'].get('rst', 0) == 0
                and r['inputs'].get('ena', 0) == 1)

    # Find whether activation ever occurs
    if not any(active(r) for r in trace):
        return (None, None, 'activation (nReset=1, rst=0, ena=1) never observed')

    glitches = []  # list of (i0,i1,i2,which_input)
    # Scan for single-sample glitches on sda_i and scl_i: A, B, A on three consecutive rows
    for i in range(1, len(trace) - 1):
        if not (active(trace[i - 1]) and active(trace[i]) and active(trace[i + 1])):
            continue
        for port in ('sda_i', 'scl_i'):
            a = trace[i - 1]['inputs'].get(port)
            b = trace[i]['inputs'].get(port)
            c = trace[i + 1]['inputs'].get(port)
            # require defined values and the A,B,A pattern with B != A
            if a is None or b is None or c is None:
                continue
            if a == c and a != b:
                glitches.append((i - 1, i, i + 1, port))

    if not glitches:
        return (None, None, 'no single-sample input glitches observed during activation')

    # Outputs that would reflect reacting to input transitions; check they stay stable
    check_ports = ['busy', 'al', 'dout', 'cmd_ack', 'scl_oen', 'sda_oen']

    for (i0, i1, i2, which) in glitches:
        r0 = trace[i0]
        r1 = trace[i1]
        r2 = trace[i2]
        # For each output, ensure no change across the three-row window
        for p in check_ports:
            v0 = r0['outputs'].get(p)
            v1 = r1['outputs'].get(p)
            v2 = r2['outputs'].get(p)
            # A change between r0->r1 indicates the design reacted at the glitch rise
            if v0 != v1:
                return (False, r1['edge'],
                        f"{which} single-sample glitch at rows {i0},{i1},{i2} caused output '{p}' change {v0} -> {v1}")
            # A change between r1->r2 indicates reaction on the glitch fall
            if v1 != v2:
                return (False, r2['edge'],
                        f"{which} single-sample glitch at rows {i0},{i1},{i2} caused output '{p}' change {v1} -> {v2}")

    return (True, None, f"{len(glitches)} single-sample input glitch(es) observed during activation with no immediate output reaction")

def decide(trace):
    # This requirement is an unconditional invariant (always). Check every
    # distinct state in the trace and fail on the first observable violation.
    # Read only declared outputs.
    for r in trace:
        out = r.get("outputs", {})

        # The design must never actively drive the external line high via the
        # dedicated 'o' outputs: they are constant 0 and the open-drain
        # enables control whether the pad is driven or released.
        if out.get("scl_o") != 0:
            return (False, r["edge"], f"scl_o driven to {out.get('scl_o')} at edge {r['edge']}; expected constant 0 (no active-high drive)")
        if out.get("sda_o") != 0:
            return (False, r["edge"], f"sda_o driven to {out.get('sda_o')} at edge {r['edge']}; expected constant 0 (no active-high drive)")

        # If the module claims to actively pull the line low (oen == 0), it
        # must not at the same time drive the line high (contradiction).
        if out.get("scl_oen") == 0 and out.get("scl_o") == 1:
            return (False, r["edge"], "scl_oen==0 while scl_o==1: contradictory drive (asserting pull-low but driving high)")
        if out.get("sda_oen") == 0 and out.get("sda_o") == 1:
            return (False, r["edge"], "sda_oen==0 while sda_o==1: contradictory drive (asserting pull-low but driving high)")

    # No violations observed across the whole trace: the module used open-drain
    # semantics (never actively drives a logic-high) and showed no contradictions.
    return (True, None, "scl_o and sda_o remained constant 0 and no oen contradictions were observed")

from specflow.refmodel.temporal import after, throughout, worst

def decide(trace):
    # Activation: at all times (invariant)
    follows = False
    windows = after(trace, lambda r: True)

    # No activation windows -> the stimulus never exercised the scenario
    if not windows:
        return (None, None, 'the activation never occurred')

    def is_zero(port):
        return lambda row: row["outputs"].get(port) == 0

    verdicts = []
    # For each invariant window, require each output be 0 throughout it.
    for w in windows:
        verdicts.append(throughout(w, is_zero("scl_o"), after_activation=follows))
        verdicts.append(throughout(w, is_zero("sda_o"), after_activation=follows))

    return worst(verdicts)

def decide(trace):
    # Activation: "at all times" (the normalized activation). We inspect the trace
    # for observable reset states because the contract guarantees that on reset
    # the output-enables are released (which reveals polarity).
    # Find rows where a reset is active: either asynchronous nReset asserted low
    # or the synchronous rst is asserted high.
    reset_rows = [r for r in trace
                  if r.get('inputs', {}).get('nReset') == 0
                  or r.get('inputs', {}).get('rst') == 1]

    # If we observed reset states, they must show the output-enables released (1).
    if reset_rows:
        for r in reset_rows:
            so = r.get('outputs', {}).get('scl_oen')
            sa = r.get('outputs', {}).get('sda_oen')
            # If either output-enable is not 1 while reset is active, polarity is wrong.
            if so != 1 or sa != 1:
                detail = (f"reset-state at edge {r.get('edge')} expected scl_oen=1 and sda_oen=1 (released), "
                          f"saw scl_oen={so} sda_oen={sa}")
                return (False, r.get('edge'), detail)
        return (True, None, f"all {len(reset_rows)} reset-state row(s) showed scl_oen=1 and sda_oen=1 (released)")

    # No reset observed in this trace; we cannot reliably determine polarity from
    # other DUT-only outputs without observing external lines, so abstain.
    return (None, None, 'no reset state observed to sample output-enable polarity')

def decide(trace):
    from specflow.refmodel.temporal import (after, edges, eventually, worst)

    # Helper to match a dict against a row's inputs/outputs
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Find the rows where rst rises (0->1)
    rst_rises = edges(trace, "rst", "rise")
    # Open on a rst rising event that occurs while nReset is inactive (nReset==1)
    opens = lambda r: (r["edge"] in rst_rises) and r["inputs"].get("nReset") == 1
    # Close the window when rst is deasserted (rst==0)
    windows = after(trace, opens, until=_any([{"rst": 0}]))

    # The reset state the spec requires:
    def in_reset_state(r):
        out = r["outputs"]
        return (
            out.get("cmd_ack") == 0 and
            out.get("busy") == 0 and
            out.get("al") == 0 and
            out.get("dout") == 0 and
            out.get("scl_oen") == 1 and
            out.get("sda_oen") == 1 and
            out.get("scl_o") == 0 and
            out.get("sda_o") == 0
        )

    # The reset effect must be observed after the clock samples rst (synchronous).
    results = [eventually(w, lambda r: in_reset_state(r), strong=True, after_activation=True)
               for w in windows]
    return worst(results)

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    # predicate builder for row matches (checks outputs then inputs as fallback)
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    # Activation: nReset == 0 (asynchronous active-low reset)
    opens = _holds({"nReset": 0})

    # Windows span the entire time nReset remains asserted (no until clause)
    windows = after(trace, opens)

    # The specification states the effect is immediate (independent of clk)
    follows = False

    # Expected reset values for the observable outputs
    expected = {
        "cmd_ack": 0,
        "busy": 0,
        "al": 0,
        "dout": 0,
        "scl_o": 0,
        "sda_o": 0,
        "scl_oen": 1,
        "sda_oen": 1,
    }

    def holds_in_row(row):
        # Check only declared outputs (fallback to inputs is harmless but not needed)
        return all(row["outputs"].get(k) == v for k, v in expected.items())

    # For each activation window, require the outputs hold these values throughout
    verdicts = [throughout(w, holds_in_row, after_activation=follows) for w in windows]
    return worst(verdicts)

from specflow.refmodel.temporal import (after, throughout, worst)

# Window predicate builders copied from the normalization guidance
def _holds(cond):
    def p(row):
        return all(
            row["outputs"].get(k, row["inputs"].get(k)) == v
            for k, v in cond.items())
    return p

def _any(alts):
    preds = [_holds(a) for a in alts]
    return lambda row: any(p(row) for p in preds)

def decide(trace):
    # Activation: ena == 0, until ena == 1; effect_follows = True per normalized data
    follows = True
    opens = _holds({"ena": 0})
    closes = _any([{"ena": 1}])

    windows = after(trace, opens, until=closes)
    # For each window: 1) scl_oen stays equal to its value at activation
    #                  2) sda_oen stays equal to its value at activation
    #                  3) cmd_ack remains 0 (no pulse) throughout
    verdicts = []
    for w in windows:
        v_scl = throughout(w, lambda r, v=w.value("scl_oen"): r["outputs"].get("scl_oen") == v,
                          after_activation=follows)
        v_sda = throughout(w, lambda r, v=w.value("sda_oen"): r["outputs"].get("sda_oen") == v,
                          after_activation=follows)
        v_cmd = throughout(w, lambda r: r["outputs"].get("cmd_ack") == 0,
                           after_activation=follows)
        verdicts.append(worst([v_scl, v_sda, v_cmd]))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, edges

    # Activation: module released from reset (normal operation)
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    opens = _holds({"nReset": 1, "rst": 0})
    windows = after(trace, opens)
    if not windows:
        return (None, None, 'module never released from reset in this trace')

    # Restrict to the moments where the observed_via says this requirement's effect is visible:
    # while the module is out of reset and enabled and the FSM is advancing (ena==1 and busy==1).
    fsm_rows = []
    for w in windows:
        for wr in w.rows:
            # w.rows entries may be either integer indices into trace or the row dicts themselves.
            if isinstance(wr, dict):
                r = wr
            else:
                # assume integer index
                r = trace[wr]
            # Use only declared ports
            if r["inputs"].get("ena") == 1 and r["outputs"].get("busy") == 1:
                fsm_rows.append(r)

    if not fsm_rows:
        return (None, None, 'no FSM-active (ena=1 and busy=1) period observed; cannot decide')

    # Find rising edges of cmd_ack anywhere in the trace
    cmd_ack_rises = edges(trace, "cmd_ack", "rise")  # set of edge numbers

    # Keep only cmd_ack events that occurred during FSM-active rows
    fsm_edge_set = set(r["edge"] for r in fsm_rows)
    events = [r for r in trace if r["edge"] in cmd_ack_rises and r["edge"] in fsm_edge_set]

    # Need at least two events to measure spacing and sensitivity to clk_cnt
    if len(events) < 2:
        return (None, None, 'not enough cmd_ack events during FSM-active periods to judge clk_cnt sensitivity')

    # Build inter-event intervals where both adjacent events observed under the same clk_cnt value
    intervals_by_cnt = {}  # clk_cnt_value -> list of index-differences between consecutive events
    for a, b in zip(events, events[1:]):
        cnt_a = a["inputs"].get("clk_cnt")
        cnt_b = b["inputs"].get("clk_cnt")
        interval = b["index"] - a["index"]
        if cnt_a is not None and cnt_a == cnt_b:
            intervals_by_cnt.setdefault(cnt_a, []).append(interval)

    # Need observations under at least two distinct clk_cnt values to compare sensitivity
    if len(intervals_by_cnt) < 2:
        return (None, None, 'not enough data under different clk_cnt values to determine sensitivity')

    # Compute average interval per clk_cnt
    avg_by_cnt = {cnt: (sum(v) / len(v)) for cnt, v in intervals_by_cnt.items()}

    # Check that increasing clk_cnt does not reduce the observed average interval
    sorted_cnts = sorted(avg_by_cnt.keys())
    for i in range(1, len(sorted_cnts)):
        smaller = sorted_cnts[i - 1]
        larger = sorted_cnts[i]
        if avg_by_cnt[larger] < avg_by_cnt[smaller]:
            # Find a concrete offending pair to point at (an adjacent-event pair under 'larger' with a short interval)
            for a, b in zip(events, events[1:]):
                if a["inputs"].get("clk_cnt") == larger and b["inputs"].get("clk_cnt") == larger:
                    interval = b["index"] - a["index"]
                    if interval <= avg_by_cnt[larger]:
                        return (False, b["edge"], f'avg interval for clk_cnt={larger} ({avg_by_cnt[larger]:.2f}) < for clk_cnt={smaller} ({avg_by_cnt[smaller]:.2f}); clk_cnt did not increase spacing; observed interval {interval}')
            # Fallback if we could not locate a specific pair
            return (False, events[0]["edge"], f'avg interval for clk_cnt={larger} ({avg_by_cnt[larger]:.2f}) < for clk_cnt={smaller} ({avg_by_cnt[smaller]:.2f}); clk_cnt did not increase spacing')

    # Special-case clk_cnt == 0: spec says timing opportunities may occur every clock.
    if 0 in intervals_by_cnt:
        min_interval_for_zero = min(intervals_by_cnt[0])
        if min_interval_for_zero != 1:
            # find the event pair showing the minimal interval and report its edge
            for a, b in zip(events, events[1:]):
                if a["inputs"].get("clk_cnt") == 0 and b["inputs"].get("clk_cnt") == 0 and (b["index"] - a["index"]) == min_interval_for_zero:
                    return (False, b["edge"], f'clk_cnt==0 observed but minimal cmd_ack inter-event interval is {min_interval_for_zero}, expected 1 (opportunities every clock)')
            return (False, events[0]["edge"], f'clk_cnt==0 observed but minimal interval is {min_interval_for_zero}, expected 1')

    # All checks passed: observed cmd_ack spacing tracked clk_cnt in the available data
    observed_cnts = sorted(avg_by_cnt.keys())
    stats = {k: round(v, 2) for k, v in avg_by_cnt.items()}
    return (True, None, f'cmd_ack event spacing tracked clk_cnt values {observed_cnts} with avg intervals {stats}')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    # effect_follows per normalized activation
    follows = True

    # Find filtered SDA/SCL transitions (sda_i/scl_i are the synchronized+filtered inputs)
    sda_falls = edges(trace, "sda_i", "fall")
    sda_rises = edges(trace, "sda_i", "rise")

    # Opening predicate: a filtered START is an SDA falling edge while SCL is high,
    # and the activation's baseline inputs must hold (ena=1, nReset=1, rst=0).
    def opens(r):
        return (
            r["edge"] in sda_falls
            and r["inputs"].get("scl_i") == 1
            and r["inputs"].get("ena") == 1
            and r["inputs"].get("nReset") == 1
            and r["inputs"].get("rst") == 0
        )

    # Closing predicate: filtered STOP (SDA rising while SCL is high) or reset
    def closes(r):
        return (
            (r["edge"] in sda_rises and r["inputs"].get("scl_i") == 1)
            or r["inputs"].get("nReset") == 0
            or r["inputs"].get("rst") == 1
        )

    # Make windows for each detected START up to the STOP or reset
    windows = after(trace, opens, until=closes)
    if not windows:
        # activation never occurred
        return worst([])

    # Find busy transitions so we can reason about rises/falls (we must look for the rise)
    busy_rises = set(edges(trace, "busy", "rise"))
    busy_falls = set(edges(trace, "busy", "fall"))

    # Inspect each START..(STOP|reset) window
    for w in windows:
        # 1) busy must RISE after the activation (not just be high already).
        ev = eventually(w, lambda r: r["edge"] in busy_rises,
                       after_activation=follows, strong=True)
        ok, edge, detail = ev
        if ok is None:
            # The window ran out of trace before busy rose -> unknown for this attempt
            return (None, None, f'activation at edge {w.edge} ran out before busy rose')
        if not ok:
            # busy did not rise in this closed window -> failure
            return (False, edge, f'busy did not assert after START (window opened at {w.edge})')

        # ev succeeded; edge is the row where busy rose
        rise_edge = edge

        # 2) Ensure busy does not fall again before the window closes.
        # A busy fall that occurs strictly after the rise and strictly before the closing row is a violation.
