    # helper: map trace-edge -> trace-index for consistent ordering
    edge_to_index = {r['edge']: r['index'] for r in trace}

    verdicts = []
    for w in windows:
        # Collect the edges (r['edge']) inside this window where scl_oen changed
        # w.rows may be row dicts; extract their 'edge' values robustly.
        try:
            window_edges = [r['edge'] for r in w.rows]
        except Exception:
            # In case w.rows holds edge numbers directly
            window_edges = list(w.rows)

        transitions = sorted(e for e in scl_change_edges if e in set(window_edges))

        if len(transitions) == 0:
            # No observable scl_oen transitions in this activation window -> cannot decide
            verdicts.append((None, None, 'no scl_oen transitions observed in this activation window'))
            continue
        if len(transitions) == 1:
            # Only one transition: insufficient evidence of periodic clk_en -> unknown
            e = transitions[0]
            verdicts.append((None, e, 'only one scl_oen transition observed; cannot determine periodic clk_en'))
            continue

        # Map transitions to their trace indices (monotonic by construction)
        try:
            positions = [edge_to_index[e] for e in transitions]
        except KeyError:
            # Defensive: if mapping fails, abstain
            verdicts.append((None, transitions[0], 'internal mapping error while locating transitions'))
            continue

        # If only two transitions, we cannot establish a repeating period reliably
        if len(positions) == 2:
            verdicts.append((None, trace[positions[0]]['edge'], 'only two transitions; cannot establish periodic spacing'))
            continue

        # Compute spacings between successive transitions (in trace-row indices)
        deltas = [positions[i+1] - positions[i] for i in range(len(positions)-1)]

        # Check that all spacings are identical (evidence of periodic, decrement-driven clk_en)
        first = deltas[0]
        if all(d == first for d in deltas):
            # PASS: observed regularly spaced scl_oen transitions in this activation window
            verdicts.append((True, trace[positions[0]]['edge'], f'observed {len(transitions)} scl_oen transitions with constant spacing {first}'))
        else:
            # FAIL: transitions occurred but spacings are not regular -> counter not decrementing each system clock
            # localise failure to the first place the spacing differs
            bad_idx = next(i for i in range(1, len(deltas)) if deltas[i] != deltas[i-1])
            edge = trace[positions[bad_idx]]['edge']
            verdicts.append((False, edge, f'scl_oen transitions present but spacings vary: deltas={deltas}'))

    return worst(verdicts)

