def decide(trace):
    # helpers from the template
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation: cmd==2, ena==1, scl_i==1; window closes on cmd_ack==1
    opens = _holds({"cmd": 2, "ena": 1, "scl_i": 1})
    closes = _any([{"cmd_ack": 1}])
    windows = after(trace, opens, until=closes)

    # Look for the release action: sda_oen rising (0->1). Compute rise edges once.
    rose = edges(trace, "sda_oen", "rise")

    # The required event: a sda_oen rise that occurs while scl_i is sampled high.
    def holds_on_release(row):
        return (row["edge"] in rose) and (row["inputs"].get("scl_i") == 1)

    # effect_follows is true in the normalized activation, so require the event after the activation row
    return worst([eventually(w, holds_on_release, after_activation=True) for w in windows])

from specflow.refmodel.temporal import after, throughout, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    applies = _holds({"cmd": 4, "ena": 1})
    closes = _any([{"scl_oen": 0}, {"cmd_ack": 1}, {"al": 1}])
    follows = True  # normalized activation.effect_follows

    windows = after(trace, applies, until=closes)

    def released_or_concluding(r):
        # sda_oen must be released throughout the READ data-bit phase, but the
        # specification pins WHILE the slave can drive the bit, and never says
        # sda_oen must still read 1 on the exact row the phase concludes (SCL
        # pulled low to end the sample window, the command completing, or
        # arbitration being lost). `closes` can only be true at the window's
        # own last row -- that is what ends it -- so this excuses the
        # requirement there and only there, while still demanding release on
        # every row strictly inside the window.
        return r["outputs"].get("sda_oen") == 1 or closes(r)

    return worst([throughout(w, released_or_concluding, after_activation=follows)
                  for w in windows])

from specflow.refmodel.temporal import after, pulse, worst

# Helper: predicate builder that matches either outputs or inputs as appropriate
def _holds(cond):
    def p(row):
        return all(
            row["outputs"].get(k, row["inputs"].get(k)) == v
            for k, v in cond.items()
        )
    return p

# Helper: any-of-alternatives (each alt is a dict that must hold together)
def _any(alts):
    preds = [_holds(a) for a in alts]
    return lambda row: any(p(row) for p in preds)

def decide(trace):
    # Normalized activation: inputs {cmd:3, ena:1}; closes on any of the until-alternatives.
    opens = _holds({"cmd": 3, "ena": 1})
    until_alts = [
        {"cmd_ack": 1},
        {"al": 1},
        {"nReset": 0},
        {"rst": 1}
    ]

    # effect_follows is true in the normalized form: evaluate the expectation after the activation row
    follows = True

    windows = after(trace, opens, until=_any(until_alts))

    verdicts = []
    for w in windows:
        # Did cmd_ack ever become 1 inside this window?
        saw_cmd_ack = any(r["outputs"].get("cmd_ack") == 1 for r in w.rows)
        if saw_cmd_ack:
            # Require exactly one-cycle-wide active pulse after the activation
            verdicts.append(pulse(w, "cmd_ack", width=1, active=1, after_activation=follows))
        else:
            # If the window contains an abort condition (al or reset) then the command did not complete normally;
            # the specification does not require cmd_ack in that aborted case, so report unknown rather than False.
            aborted = (
                any(r["outputs"].get("al") == 1 for r in w.rows)
                or any(r["inputs"].get("nReset") == 0 for r in w.rows)
                or any(r["inputs"].get("rst") == 1 for r in w.rows)
            )
            if aborted:
                verdicts.append((None, None, "activation aborted by al/nReset/rst before cmd_ack; completion pulse not expected"))
            else:
                # No cmd_ack observed and no abort seen in this window: the trace ended or the response did not occur yet -> unknown
                verdicts.append((None, None, "no cmd_ack observed in activation window"))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import (after, throughout, worst, edges)

    # Activation predicate (from normalized block)
    activation_inputs = {"cmd": 4, "din": 0, "ena": 1, "nReset": 1, "rst": 0}
    follows = True  # effect_follows from normalized block

    # Helper: read a named port value from outputs or inputs (declared ports only)
    def _val(row, name):
        return row["outputs"].get(name, row["inputs"].get(name))

    # Predicate that checks a dict of level conditions (numeric equality only)
    def _holds(cond):
        def p(row):
            for k, v in cond.items():
                # Edge specifications are handled separately; this only matches numeric levels
                if isinstance(v, str):
                    return False
                if _val(row, k) != v:
                    return False
            return True
        return p

    # Build the list of until-alternative predicates from the normalized block
    until_alts = [{"scl_oen": "fall"}, {"al": 1}, {"cmd_ack": 1}]
    until_preds = []
    for alt in until_alts:
        # If the alt contains an edge specification ("rise"/"fall"/"change"),
        # compute the edge set now and make a predicate that tests membership.
        edge_port = None
        edge_kind = None
        for k, v in alt.items():
            if isinstance(v, str):
                edge_port = k
                edge_kind = v
                break
        if edge_port is not None:
            edge_set = edges(trace, edge_port, edge_kind)
            # other (non-edge) clauses in the same alt, if any
            other = {k: v for k, v in alt.items() if not isinstance(v, str)}
            other_pred = _holds(other) if other else (lambda r: True)
            def _make_edge_pred(es, op):
                return lambda r: (r["edge"] in es) and op(r)
            until_preds.append(_make_edge_pred(edge_set, other_pred))
        else:
            until_preds.append(_holds(alt))

    def _any(preds):
        return lambda r: any(p(r) for p in preds)

    # Window: when the WRITE bit-phase with din==0 is active, until any until-alt fires
    windows = after(trace, _holds(activation_inputs), until=_any(until_preds))

    # Expectation: sda_oen == 0 throughout each window, evaluated after the activation row
    checks = [throughout(w, lambda r: r["outputs"].get("sda_oen") == 0, after_activation=follows)
              for w in windows]
    return worst(checks)

def decide(trace):
    from specflow.refmodel.temporal import after, worst

    # Activation predicate builder (matches both inputs and outputs by key)
    def _holds(cond):
        def p(row):
            return all(
                (row["outputs"].get(k, row["inputs"].get(k)) == v)
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Normalized activation: cmd=2, din=1, ena=1, nReset=1, rst=0, scl_i=1
    opens = _holds({"cmd": 2, "din": 1, "ena": 1, "nReset": 1, "rst": 0, "scl_i": 1})
    # until: scl_oen==0 OR al==1 OR cmd_ack==1
    closes = _any([{"scl_oen": 0}, {"al": 1}, {"cmd_ack": 1}])

    windows = after(trace, opens, until=closes)

    verdicts = []
    for w in windows:
        rows = w.rows
        # Find rows in this window where the controller expects SDA released high
        # (din==1) but the observed sda_i is low -> arbitration detect.
        detections = [r for r in rows if r["inputs"].get("din") == 1 and r["inputs"].get("sda_i") == 0]

        if not detections:
            # No arbitration observed in this activation window: vacuously satisfied
            verdicts.append((True, None, f'no arbitration-detect in window starting at edge {w.edge}'))
            continue

        # For each detection, require al==1 at or after the detection row within the same window.
        failed = None
        for d in detections:
            d_index = d["index"]
            # search for any row in window at or after this detection where al==1
            found_al = any((r["outputs"].get("al") == 1) and (r["index"] >= d_index) for r in rows)
            if not found_al:
                failed = d
                break
        if failed is not None:
            verdicts.append((False, failed["edge"], f'arbitration detected (din=1,sda_i=0) at edge {failed["edge"]} but al was not asserted later in the same WRITE high-phase'))
        else:
            verdicts.append((True, None, f'arbitration detections all followed by al in window starting at edge {w.edge}'))

    return worst(verdicts)

from specflow.refmodel.temporal import after, eventually, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    activation = _holds({"cmd": 4, "din": 1, "ena": 1, "nReset": 1, "rst": 0})
    closes = _holds({"cmd_ack": 1})
    # Reset during a command voids the attempt rather than ending it --
    # 'Reset during a command releases both bus lines and suppresses
    # acknowledgement' -- so it belongs beside arbitration loss in aborts,
    # not left unguarded to run the window off the end of the trace.
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])

    windows = after(trace, activation, until=closes, aborts=aborts)

    return worst([
        eventually(w, lambda r: r["outputs"].get("scl_oen") == 0,
                   after_activation=True, strong=True)
        for w in windows
    ])

