def decide(trace):
    # effect_follows comes from the normalized activation
    follows = True

    # detect synchronous rst assertion as a rising edge
    rst_rises = edges(trace, "rst", "rise")

    # open on either asynchronous nReset==0 OR rst rising while nReset==1
    def opens(row):
        return row["inputs"].get("nReset") == 0 or (
            row["edge"] in rst_rises and row["inputs"].get("nReset") == 1)

    # the window closes when reset is released (nReset==1) OR rst returns low
    windows = after(trace, opens, until=_any([{"nReset": 1}, {"rst": 0}]))

    # expected idle/reset output values (only declared outputs checked)
    expected = {
        "cmd_ack": 0,
        "busy": 0,
        "al": 0,
        "dout": 0,
        "scl_o": 0,
        "scl_oen": 1,
        "sda_o": 0,
        "sda_oen": 1,
    }

    def holds(row):
        return all(row["outputs"].get(k) == v for k, v in expected.items())

    return worst([throughout(w, holds, after_activation=follows) for w in windows])

