def decide(trace):
    # Find rows where reset is active: asynchronous nReset==0 or synchronous rst==1.
    reset_rows = [r for r in trace
                  if r.get('inputs', {}).get('nReset') == 0
                  or r.get('inputs', {}).get('rst') == 1]
    # If reset never occurred in this trace, abstain.
    if not reset_rows:
        return (None, None, 'reset (nReset low or rst high) never observed in this trace')
    # At every row where reset is active, cmd_ack must be deasserted (0).
    for r in reset_rows:
        cmd_ack = r.get('outputs', {}).get('cmd_ack')
        if cmd_ack == 1:
            return (False, r.get('edge'), 'cmd_ack asserted while reset is active')
    # All observed reset rows showed cmd_ack cleared.
    return (True, None, f'cmd_ack deasserted during {len(reset_rows)} reset row(s)')

