# Helper to test a row against a dict of port:value pairs (inputs or outputs)
def _holds(cond):
    def p(row):
        return all(
            row["outputs"].get(k, row["inputs"].get(k)) == v
            for k, v in cond.items())
    return p

# Any-of-alternatives: a list of dicts where any single dict holding opens the window
def _any(alts):
    preds = [_holds(a) for a in alts]
    return lambda row: any(p(row) for p in preds)

def decide(trace):
    # effect_follows from normalized activation
    follows = True

    # activation opens on either async nReset==0 or sync (nReset==1 and rst==1)
    opens_on = [
        {"nReset": 0},
        {"nReset": 1, "rst": 1}
    ]

    # window closes when either nReset returns to 1 or rst returns to 0
    until_alts = [
        {"nReset": 1},
        {"rst": 0}
    ]

    # Build the antecedent windows exactly as normalized
    windows = after(trace, _any(opens_on), until=_any(until_alts))

    # Predicate: both status flags are cleared (0)
    def cleared(row):
        return row["outputs"].get("busy") == 0 and row["outputs"].get("al") == 0

    # For every activation window, the outputs must be 0 throughout the window,
    # evaluated after the activation row because effect_follows is True.
    return worst([throughout(w, cleared, after_activation=follows) for w in windows])

from specflow.refmodel.temporal import edges

def decide(trace):
    # Find all nReset rising edges (release from reset)
    release_edges = edges(trace, 'nReset', 'rise')
    if not release_edges:
        return (None, None, 'no nReset release seen in trace')

    # Precompute sda edges and busy checks
    sda_falls = sorted(edges(trace, 'sda_i', 'fall'))
    sda_rises = sorted(edges(trace, 'sda_i', 'rise'))

    found_any = False

    # Helper: find row index for a given edge value
    def row_index_for_edge(e):
        for i, r in enumerate(trace):
            if r.get('edge') == e:
                return i
        return None

    for rel_edge in sorted(release_edges):
        rel_idx = row_index_for_edge(rel_edge)
        if rel_idx is None:
            continue
        rel_row = trace[rel_idx]
        # Ensure rst is inactive on release (observed_via.when requires rst==0)
        if rel_row['inputs'].get('rst', 0) != 0:
            continue
        # Require ena==1 and external SCL sampled high at the release moment
        if rel_row['inputs'].get('ena', 0) != 1:
            continue
        if rel_row['inputs'].get('scl_i', 1) != 1:
            continue

        # Find the first sda fall after release, then the next sda rise after that
        later_falls = [e for e in sda_falls if e > rel_edge]
        if not later_falls:
            continue
        fall_edge = later_falls[0]
        later_rises = [e for e in sda_rises if e > fall_edge]
        if not later_rises:
            # no rising edge after the fall -> not the short glitch scenario we look for
            continue
        rise_edge = later_rises[0]

        # We have a post-reset short pulse candidate (fall then rise). Mark that we saw the activation.
        found_any = True

        fall_idx = row_index_for_edge(fall_edge)
        rise_idx = row_index_for_edge(rise_edge)
        if fall_idx is None or rise_idx is None:
            continue

        # Check busy across the interval from the release row through the end of the pulse (inclusive).
        # If busy asserts anywhere in that interval the short glitch produced a START and the requirement is violated.
        for j in range(rel_idx, rise_idx + 1):
            busy_val = trace[j]['outputs'].get('busy', 0)
            if busy_val == 1:
                edge = trace[j].get('edge')
                detail = (f'busy asserted at edge {edge} in response to a short sda_i pulse after nReset release '
                          f'(release_edge={rel_edge}, fall_edge={fall_edge}, rise_edge={rise_edge})')
                return (False, edge, detail)
        # If we reach here, this glitch was rejected (busy stayed 0). Continue checking other releases.

    if not found_any:
        return (None, None, 'no post-reset short-sda glitch scenario observed while ena=1 and scl_i=1')

    # All observed post-reset short pulses were rejected: pass.
    return (True, None, 'post-reset short sda_i glitches were rejected; busy remained 0')

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst, edges

    # Build predicate from simple dicts (normalized-style)
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Where scl_oen rose (release event)
    rose = edges(trace, "scl_oen", "rise")

    # Open on the rise of scl_oen while filtered SCL is low.
    def opens_on(row):
        return (
            row["edge"] in rose
            and row["outputs"].get("scl_oen") == 1
            and row["inputs"].get("scl_i") == 0
        )

    # Window closes when scl_i goes high OR when scl_oen is driven low again.
    windows = after(trace, opens_on, until=_any([{"scl_i": 1}, {"scl_oen": 0}]))

    # effect_follows comes from the normalized activation
    follows = True

    verdicts = []
    for w in windows:
        # Predicate: accept rows where scl_oen==1. Allow a final closing row to show scl_oen==0
        # (that re-assertion is the explicit close and should not be flagged).
        def p(row, _w=w):
            # If line is released, that's fine
            if row["outputs"].get("scl_oen") == 1:
                return True
            # If scl_oen == 0, accept it only if this window closed here (and so this
            # row is the final row of the window). Determine the final row index robustly.
            if _w.closed:
                try:
                    last = _w.rows[-1]
                    last_idx = last if isinstance(last, int) else last.get("index", None)
                except Exception:
                    last_idx = None
                # Compare against the row's index; if this is the closing row, allow it.
                if last_idx is not None and row.get("index") == last_idx and row["outputs"].get("scl_oen") == 0:
                    return True
            # Otherwise it's a violation: scl_oen not held released during the wait
            return False

        verdicts.append(throughout(w, lambda r: p(r), after_activation=follows))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, edges, worst

    # Find rows where filtered SCL fell
    fell = edges(trace, "scl_i", "fall")

    # Window opens on the filtered falling SCL event while this master had released SCL
    def opens(r):
        return r["edge"] in fell and r["outputs"].get("scl_oen") == 1

    windows = after(trace, opens)

    # The normalized activation's effect_follows is False: the observable effect
    # may be at the activation row or any time afterwards. Preserve that.
    follows = False

    # No activation -> unknown
    if not windows:
        return worst([])

    verdicts = []

    # For each activation, look forward in the trace for any state where scl_oen
    # differs from its value at the activation. That difference is the observable
    # FSM-driven alignment the requirement promises. Do not demand it on a
    # particular next edge; accept any later observable change.
    for w in windows:
        init = w.value("scl_oen")
        seen = None
        for r in trace:
            # Start checking at the activation row if effect_follows is False,
            # otherwise start strictly after it.
            if follows:
                if r["edge"] <= w.edge:
                    continue
            else:
                if r["edge"] < w.edge:
                    continue
            cur = r["outputs"].get("scl_oen")
            if cur != init:
                seen = (True, r["edge"], f'scl_oen changed from {init} to {cur} at edge {r["edge"]}')
                break
        if seen is None:
            # activation happened but no observable scl_oen change was ever seen
            verdicts.append((False, w.edge, 'no FSM-driven change to scl_oen observed after the falling SCL event'))
        else:
            verdicts.append(seen)

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, edges, worst

    # predicate for the activation: ena=1, nReset=1, rst=0
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    applies = _holds({"ena": 1, "nReset": 1, "rst": 0})
    windows = after(trace, applies)  # until=[] in normalized -> window ends when activation stops

    verdicts = []
    # precompute edges where scl_oen changed (as edge numbers)
    scl_edges = edges(trace, "scl_oen", "change")

    for w in windows:
        # collect the rows (states) in this window where scl_oen changed
        change_rows = [r for r in w.rows if r["edge"] in scl_edges]
        if not change_rows:
            # nothing to judge in this window: abstain for this window
            verdicts.append((None, None, "no scl_oen transitions seen in window"))
            continue

        # sample the configured prescale at the activation row; if not present, abstain
        try:
            cfg = w.value("clk_cnt")
        except Exception:
            # w.value may raise if port absent; be conservative and abstain
            verdicts.append((None, None, "clk_cnt not available at activation"))
            continue

        # If clk_cnt is >= 2, the counter implies spacing larger than a trivial every-edge case;
        # the specification allows clk_cnt==0 (every eligible clk edge) and clk_cnt==1 (very frequent),
        # so we only flag the obvious violation: scl_oen changing on every distinct system-clock row
        # while clk_cnt >= 2. We compute deltas in trace-order (using index) between consecutive
        # change rows inside the window; a delta of 1 means the design changed scl_oen on consecutive
        # distinct states.
        if cfg is None:
            verdicts.append((None, None, "clk_cnt unknown at activation"))
            continue

        try:
            cfg_int = int(cfg)
        except Exception:
            # non-integer clk_cnt is unexpected; abstain rather than fail
            verdicts.append((None, None, f"clk_cnt not interpretable ({cfg})"))
            continue

        # Sort by trace index to get chronological order
        change_rows.sort(key=lambda r: r["index"])
        indices = [r["index"] for r in change_rows]

        # If configuration permits every-edge ticks (clk_cnt 0 or 1), do not flag frequent transitions
        if cfg_int <= 1:
            verdicts.append((True, None, f"clk_cnt={cfg_int} permits frequent scl_oen changes"))
            continue

        # For cfg_int >= 2, require that not every change is on the next distinct state.
        # Fail if any pair of consecutive scl_oen changes inside the window are adjacent (delta==1).
        bad_row = None
        for i in range(1, len(indices)):
            if indices[i] - indices[i - 1] == 1:
