def decide(trace):
    # Look only for the operational moments the normalized 'when' describes:
    # nReset==1, rst==0, ena==1, and an FSM-driven observable change on
    # either cmd_ack or scl_oen compared with the previous distinct state.
    if len(trace) < 2:
        return (None, None, 'no opportunity observed (trace too short)')

    for i in range(1, len(trace)):
        prev = trace[i-1]
        cur = trace[i]
        # only consider rows where the module is operational
        inputs = cur.get('inputs', {})
        if not (inputs.get('nReset') == 1 and inputs.get('rst') == 0 and inputs.get('ena') == 1):
            continue
        # compare declared outputs for a change that signals an FSM phase advance
        prev_out = prev.get('outputs', {})
        cur_out = cur.get('outputs', {})
        changed_ports = []
        for p in ('cmd_ack', 'scl_oen'):
            if prev_out.get(p) != cur_out.get(p):
                changed_ports.append((p, prev_out.get(p), cur_out.get(p)))
        if changed_ports:
            # The normalized 'effect_follows' is false, so the observable
            # consequence may appear at the activation row itself.
            detail = ('observed operational output change(s) at edge {}: '.format(cur.get('edge')) +
                      ', '.join("{} {}->{}".format(p, a, b) for (p, a, b) in changed_ports))
            return (True, cur.get('edge'), detail)

    # No operational FSM-driven observable change was seen; the activation
    # (counter expiry producing an externally-observable effect) did not occur
    # in this trace as far as boundary-visible ports reveal.
    return (None, None, 'no operational FSM phase-advance observed on cmd_ack or scl_oen; activation not seen')

