        anchor_edge = rows[anchor_idx]["edge"]
        found = any(r["outputs"].get("dout") == expected
                    for r in rows[anchor_idx:])

        if found:
            per_window.append((True, anchor_edge,
                f'dout reached the sampled SDA value ({expected}) after the '
                f'SCL-high sampling phase began at edge {anchor_edge}'))
