def decide(trace):
    # Decide from declared ports only. We treat a supported sequence completion
    # as the rising cmd_ack event and check that cmd_ack is a one-system-clock
    # pulse. The FSM being idle is observable via released open-drain enables
    # (sda_oen==1 and scl_oen==1). The specification does not fix how many
    # distinct states after the cmd_ack pulse those outputs must show idle, so
    # we accept the enables appearing at the same row or any later distinct row
    # in the trace. If the trace ends before the idle enables are observed we
    # return (None, ...) because the stimulus did not let us decide.
    from specflow.refmodel.temporal import edges

    def _holds(cond):
        def p(row):
            return all(row["inputs"].get(k) == v for k, v in cond.items())
        return p

    # Activation: ena=1, nReset=1, rst=0
    activates = _holds({"ena": 1, "nReset": 1, "rst": 0})

    # Find rows where cmd_ack rose
    rises = edges(trace, "cmd_ack", "rise")

    # Matches are cmd_ack rise rows that occur while the activation inputs hold
    matches = [(i, r) for i, r in enumerate(trace) if r["edge"] in rises and activates(r)]

    if not matches:
        # No completion observed while enabled and out-of-reset
        return (None, None, "no command-completion (cmd_ack rise) observed while ena=1, nReset=1, rst=0")

    for idx, r in matches:
        # cmd_ack must be asserted on the rise row
        if r["outputs"].get("cmd_ack", 0) != 1:
            return (False, r["edge"], "cmd_ack rise row does not show cmd_ack=1")
        # The spec fixes cmd_ack as a one-system-clock pulse; the trace's 'held'
        # counts distinct clock edges this state lasted, so require held == 1.
        if r.get("held", 1) != 1:
            return (False, r["edge"], f"cmd_ack held for {r.get('held', 1)} edges, expected exactly 1")

        # Check for idle-observable enables at the same row or any later distinct row
        sda_here = r["outputs"].get("sda_oen")
        scl_here = r["outputs"].get("scl_oen")
        if sda_here == 1 and scl_here == 1:
            # idle observable already at the same row
            continue

        found = False
        # Search forward for a later distinct state where both enables are released.
        for j in range(idx + 1, len(trace)):
            t = trace[j]
            if t["outputs"].get("sda_oen") == 1 and t["outputs"].get("scl_oen") == 1:
                found = True
                break
        if found:
            continue

        # We saw the cmd_ack completion but did not observe the idle enables
        # released before the trace ended; this is unknown rather than a
        # failure because the specification leaves the latency unspecified.
        return (None, r["edge"], "trace ended before idle outputs (sda_oen/scl_oen) were observed after cmd_ack")

    # All observed completions had a one-clock cmd_ack and the idle enables
    # were observed at or after completion.
    return (True, None, f"{len(matches)} command completion(s) observed with cmd_ack single-clock pulse and idle enables released at or after completion")

