    for r in scl_rows:
        if r["outputs"].get("scl_o") != 0:
            return (False, r["edge"],
                     'scl_oen == 0 (SCL actively driven low) but scl_o != 0')
    for r in sda_rows:
        if r["outputs"].get("sda_o") != 0:
            return (False, r["edge"],
                     'sda_oen == 0 (SDA actively driven low) but sda_o != 0')

    return (True, None,
            f'{len(scl_rows)} row(s) with scl_oen==0 and {len(sda_rows)} row(s) '
            'with sda_oen==0 all showed the corresponding constant-low drive '
            'output at 0')

def decide(trace):
    from specflow.refmodel.temporal import after, pulse, worst

    # predicate over a row: test outputs first, then inputs (as helpers do)
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    # any-of-alternatives: each alternative is a dict that must hold together
    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # effect_follows comes from the normalized block
    follows = True

    # Activation: core able to run (ena=1, nReset=1, rst=0). Window closes on cmd_ack or al.
    windows = after(trace,
                    _holds({"ena": 1, "nReset": 1, "rst": 0}),
                    until=_any([{"cmd_ack": 1}, {"al": 1}]))

    # Expect exactly one-clock pulse of cmd_ack after the activation (effect_follows=True)
    return worst([pulse(w, "cmd_ack", width=1, active=1, after_activation=follows)
                  for w in windows])
